/* Day-navigable free-time scoreboard. Loads data/calendar.json (generated by tools/generate_calendar.py). */
(function(){
  const state = { data:null, idx:0 };
  const $ = (s)=>document.querySelector(s);
  function fmt(min){ min=Math.round(min); const h=Math.floor(min/60), m=min%60;
    const ap = h>=12 ? 'PM':'AM'; const hh = h%12===0?12:h%12;
    return hh+":"+String(m).padStart(2,"0")+" "+ap; }
  function load(){
    fetch("data/calendar.json").then(r=>r.json()).then(d=>{
      state.data=d;
      const today=new Date().toISOString().slice(0,10);
      let i=d.days.findIndex(x=>x.date===today);
      state.idx = i>=0? i : 0;
      const dp=$("#datepick"); dp.min=d.days[0].date; dp.max=d.days[d.days.length-1].date;
      dp.value=d.days[state.idx].date;
      render();
    });
  }
  function render(){
    const d=state.data, day=d.days[state.idx];
    $("#datepick").value=day.date;
    $("#daylabel").textContent = new Date(day.date+"T12:00:00").toLocaleDateString("en-US",{weekday:"long",year:"numeric",month:"long",day:"numeric"});
    const overallTag = day.overall==="FREE" ? '<span class="tag free">FREE — no live radio sports</span>'
      : day.overall==="PARTIAL" ? '<span class="tag partial">PARTIAL — free windows below</span>'
      : '<span class="tag busy">BUSY</span>';
    const verTag = day.verified ? '<span class="tag verified">VERIFIED anchors</span>' : '<span class="tag estimated">ESTIMATED (schedule not officially released)</span>';
    let cats = Object.entries(day.cats).map(([k,v])=>{
      const lbl={mlb:"MLB (all 30)",nfl:"NFL + Westwood One",ncaaf:"Stanford / Cal NCAAF"}[k];
      const cls = v==="off"?"off":(v==="allstar"?"free":"busy");
      return `<span class="tag ${cls}">${lbl}: ${v.toUpperCase()}</span>`;
    }).join(" ");
    // 24h bar
    let barHtml="";
    if(day.busy.length){
      day.busy.forEach(b=>{ barHtml+=`<div class="b" style="width:${(b.end-b.start)/1440*100}%" title="${b.label}"></div>`; });
    } else { barHtml='<div class="f" style="width:100%"></div>'; }
    let rows="";
    day.busy.forEach(b=>{ rows+=`<div class="row"><div class="t">${fmt(b.start)} – ${fmt(b.end)} PT</div><div><span class="tag busy">BUSY</span> ${b.label}</div></div>`; });
    day.free.forEach(f=>{ if(f.end-f.start>=15) rows+=`<div class="row"><div class="t">${fmt(f.start)} – ${fmt(f.end)} PT</div><div><span class="tag free">FREE</span> ${(f.end-f.start)/60} h free</div></div>`; });
    $("#daycard").innerHTML = `
      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">${overallTag} ${verTag} <span class="badge">Free time today: <b>${day.freeHours.toFixed(1)} h</b> (Pacific)</span></div>
      <div style="margin:10px 0">${cats}</div>
      <div class="bar">${barHtml}</div>
      <div class="note">Bar = 24 h Pacific day: <span style="color:var(--bad)">red = live radio sports on air (est. typical windows)</span>, green = free. Game-level times for future seasons are TBD until official releases; windows use verified averages (MLB 2:38, NFL 3:03, NCAAF ~3:26).</div>
      <div class="timeline" style="margin-top:10px">${rows||'<div class="row"><div class="t">all day</div><div><span class="tag free">FREE</span> 24 h — no MLB, NFL, Stanford/Cal NCAAF, or Westwood One NFL on the radio</div></div>'}</div>
      ${day.note?`<div class="note" style="margin-top:8px">⚠ ${day.note}</div>`:""}
      <div class="note" style="margin-top:8px">Sources: MLB 2027 schedule release (mlb.com), 2027 Spring Training release (mlb.com), NFL 2026 key dates + Super Bowl LXI Feb 14 2027 (nfl.com / Westwood One), Cal & Stanford 2027 announcements (calbears.com / gostanford.com). See <a href="flagged.html">Flagged for Review</a> for unverified items.</div>`;
    $("#prev").disabled = state.idx===0;
    $("#next").disabled = state.idx===d.days.length-1;
  }
  document.addEventListener("DOMContentLoaded",()=>{
    load();
    $("#prev").onclick=()=>{ if(state.idx>0){state.idx--;render();} };
    $("#next").onclick=()=>{ if(state.idx<state.data.days.length-1){state.idx++;render();} };
    $("#today").onclick=()=>{ const t=new Date().toISOString().slice(0,10); const i=state.data.days.findIndex(x=>x.date===t); if(i>=0){state.idx=i;render();} };
    $("#datepick").onchange=(e)=>{ const i=state.data.days.findIndex(x=>x.date===e.target.value); if(i>=0){state.idx=i;render();} };
  });
})();
